// --- node body ---
// A daily one-page watcher for a round that opens with no warning and closes
// fast once it does (HOUSING_PLAN.md / LEARN_PLAN.md context: this is the prime
// kollegie next to campus). `egmontRoundStatus` only ever recognises the CLOSED
// sentence; absence of it — an open round, a reworded page, a redesign, or a
// fetch that came back empty or as an error page — is the alert condition, not
// evidence of any one of those in particular.
//
// `onError: continueRegularOutput` + `neverError: true` on the fetch node mean a
// DNS failure, a timeout or a non-2xx response ALL still reach this node as one
// item rather than failing the run — a watcher that goes red and stops on a
// blip is a watcher that silently stops watching. What is distinguished HERE,
// once, is only "did a request complete at all": that decides which subject the
// alert uses downstream, never the closed/open verdict itself, which stays a
// pure function of the page text.
const item = $input.first().json || {};
const fetchFailed = Boolean(item.error) && !item.data && !item.body;
const html = item.data ?? item.body ?? '';

const result = egmontRoundStatus(html);
console.log(
  'egmont: status=' + result.status + ' marker_found=' + result.marker_found +
    (fetchFailed ? ' (fetch failed: ' + JSON.stringify(item.error).slice(0, 200) + ')' : ''),
);

return [{ json: { ...result, fetch_failed: fetchFailed, checked_at: new Date().toISOString() } }];

// --- node body ---
// Reached only on the FALSE branch of "Round Still Closed?" — status is
// `open_or_changed`, for whichever of its reasons. Two subjects, not one: a
// genuine fetch failure gets its own honest wording rather than being dressed
// up as "the round looks open", which would be a claim this run cannot back.
//
// No database, no seen-state, nothing persisted anywhere. The page IS the
// state — this sends every day the marker stays missing, on purpose. Rounds
// are short once open (HOUSING_PLAN.md §2's asymmetry, same shape as the
// waiting-list renewal guard: better an email he has seen nineteen times than
// the one time it mattered arriving zero times.
const row = $input.first().json || {};
const TO = $env.JOB_NOTIFY_TO || 'bastianrthomsen@gmail.com';
const url = 'https://egmontkollegiet.dk/';

const escapeHtml = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const subject = row.fetch_failed
  ? 'Egmont-vagten kunne ikke læse siden'
  : '🏠 Egmont: ansøgningsrunden ser ÅBEN ud — søg nu';

const detail = row.fetch_failed
  ? 'Det daglige tjek kunne ikke hente egmontkollegiet.dk i morges. Det kan være ' +
    'en midlertidig netværksfejl eller at siden er lagt om — det ved denne mail ikke, ' +
    'og siger det derfor ligeud i stedet for at gætte.'
  : 'Sætningen "Ansøgningsrunden er lukket." findes ikke længere på forsiden. Det kan ' +
    'betyde runden er åbnet — men det kan også være en omformulering eller en ny ' +
    'sideopsætning. Tjek selv, og søg med det samme hvis runden rent faktisk er åben.';

const html =
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" ' +
  'style="background:#f4f5f7;margin:0;padding:20px 0;"><tr><td align="center" style="padding:0 12px;">' +
  '<table role="presentation" width="560" cellpadding="0" cellspacing="0" border="0" ' +
  'style="width:100%;max-width:560px;background:#ffffff;border:2px solid #2f6feb;border-radius:12px;' +
  "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;" +
  'color:#16181d;text-align:left;">' +
  '<tr><td style="padding:22px 22px 12px 22px;">' +
  '<div style="display:inline-block;background:#2f6feb;color:#ffffff;border-radius:999px;' +
  'padding:6px 16px;font-size:15px;font-weight:700;">' + escapeHtml(row.fetch_failed ? 'fetch failed' : 'round looks open') + '</div>' +
  '<div style="font-size:19px;font-weight:700;line-height:26px;margin-top:14px;">Egmont Kollegiet</div>' +
  '<div style="font-size:14px;color:#3a3f47;margin-top:8px;line-height:20px;">' + escapeHtml(detail) + '</div>' +
  '</td></tr>' +
  '<tr><td style="padding:8px 22px 22px 22px;">' +
  '<a href="' + escapeHtml(url) + '" style="display:block;background:#2f6feb;color:#ffffff;' +
  'font-size:17px;font-weight:700;padding:16px 20px;border-radius:10px;text-decoration:none;' +
  'text-align:center;">Åbn egmontkollegiet.dk &rarr;</a>' +
  '</td></tr>' +
  '<tr><td style="padding:0 22px 18px 22px;border-top:1px solid #eceef1;">' +
  '<div style="font-size:11px;color:#9aa0a6;padding-top:12px;line-height:16px;">' +
  'checked ' + escapeHtml(row.checked_at || '') + ' &middot; this mail repeats every day at 09:00 ' +
  'until the site says "Ansøgningsrunden er lukket." again — rounds are short, so the ' +
  'repetition is the point, not a bug' +
  '</div></td></tr>' +
  '</table></td></tr></table>';

const text = [
  subject,
  '',
  detail,
  '',
  'Open: ' + url,
  '',
  'checked ' + (row.checked_at || ''),
  'This will repeat daily until the site says "Ansøgningsrunden er lukket." again.',
].join('\n');

return [{ json: { to: TO, subject, html, text } }];
